s=s.replace("    // The tier is not yet part of the production API; this seam is the only place to change once it is.\n","")
s=s.replace("For(subtotalCents)","For(Enum.Parse<LoyaltyTier>(tier), subtotalCents)")
open(p,'w').write(s)
EOF
